from solution import words_string

import pytest
from hypothesis import given
import hypothesis.strategies as st


def _reference(s):
    # Obviously-correct model from spec literal:
    # split on commas or spaces, drop empties, preserve order.
    words = []
    cur = []
    for ch in s:
        if ch == "," or ch == " ":
            if cur:
                words.append("".join(cur))
                cur = []
        else:
            cur.append(ch)
    if cur:
        words.append("".join(cur))
    return words


def test_examples_given_in_spec():
    assert words_string("Hi, my name is John") == ["Hi", "my", "name", "is", "John"]
    assert words_string("One, two, three, four, five, six") == ["One", "two", "three", "four", "five", "six"]


def test_empty_string_returns_empty_list():
    assert words_string("") == []


def test_only_delimiters_returns_empty_list():
    assert words_string(" ") == []
    assert words_string(",") == []
    assert words_string(" , ,   ,,  , ") == []
    assert words_string(",,,") == []
    assert words_string("   ") == []


def test_single_word_without_delimiters():
    assert words_string("hello") == ["hello"]
    assert words_string("John") == ["John"]
    assert words_string("a") == ["a"]


@given(st.text(alphabet=st.sampled_from(["a", "b", "Z", "0", " ", ","]), max_size=20))
def test_reference_model_equivalence(s):
    assert words_string(s) == _reference(s)


@given(st.text(alphabet=st.sampled_from(["a", "b", "x", " ", ","]), max_size=20))
def test_no_empty_words_in_result(s):
    result = words_string(s)
    assert isinstance(result, list)
    for w in result:
        assert isinstance(w, str)
        assert w != ""


@given(st.text(alphabet=st.sampled_from(["a", "b", "x", " ", ","]), max_size=20))
def test_words_contain_no_comma_or_space(s):
    for w in words_string(s):
        assert "," not in w
        assert " " not in w


@given(st.text(alphabet=st.sampled_from(["a", "b", "x", " ", ","]), max_size=20))
def test_comma_space_interchangeability(s):
    # Commas and spaces are equivalent separators per spec.
    assert words_string(s) == words_string(s.replace(",", " "))
    assert words_string(s) == words_string(s.replace(" ", ","))


@given(st.text(alphabet=st.sampled_from(["a", "b", "x", " ", ","]), max_size=20))
def test_join_roundtrip_idempotence(s):
    words = words_string(s)
    assert words_string(" ".join(words)) == words
    assert words_string(", ".join(words)) == words
    assert words_string(",".join(words)) == words


@given(st.text(alphabet=st.sampled_from(["a", "b", "x", " ", ","]), max_size=20))
def test_concatenation_covers_non_delimiter_characters(s):
    # Removing delimiters from input equals concatenating output words.
    words = words_string(s)
    stripped = s.replace(",", "").replace(" ", "")
    assert "".join(words) == stripped


@given(st.text(alphabet=st.sampled_from(["a", "b", "x", " ", ","]), max_size=20))
def test_extra_delimiters_do_not_change_words(s):
    words = words_string(s)
    if not words:
        return
    # Doubling every delimiter should not change the word list.
    doubled = []
    for ch in s:
        if ch == "," or ch == " ":
            doubled.append(ch)
            doubled.append(ch)
        else:
            doubled.append(ch)
    assert words_string("".join(doubled)) == words
    # Adding leading/trailing delimiters should not change the word list.
    assert words_string(" , " + s + " , ") == words
